pub fn transform(xs: &[i64], lo: i64, hi: i64) -> i64 {
    xs.iter()
        .map(|&x| (if x % 2 != 0 { x * 3 } else { x }).max(lo).min(hi))
        .sum()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_transform() {
        assert_eq!(transform(&[1, 2, 3, -4], 0, 5), 9);
        assert_eq!(transform(&[], 0, 1), 0);
    }
}
